		Help: "Indicates if the orchestrator service is up (1) or down (0).",
	})
)

func RegisterMetrics(reg prometheus.Registerer) error {
	// Stub implementation
	if err := reg.Register(OrchestratorHealthStatus); err != nil {
		return err
	}
	if err := reg.Register(TaskStateCount); err != nil {
		return err
	}
